public IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
	// Initialize the mapping from the input graph to itself
	IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>(graph, graph);

	// Iterate through each vertex in the graph
	for (V vertex : graph.vertices()) {
		// Add the vertex to the mapping with a self-loop
