private static int getPrime(int n) {
    if (n <= 3) {
        return n;
    } else if (n % 2 == 0 || n % 3 == 0) {
        return getPrime(n - 1);
    } else {
        int p = (int) Math.sqrt(n);
        for (int i = 2; i <= p; i++) {
