public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i == str.length()) {
                throw new Exception("Invalid escape sequence at end of string: " + str);
            }
            c = str.charAt(i);
            if (c == 'u') {
                if (i + 4 < str.length()) {
                    String hex = str.substring(i + 1, i + 5);
                    int cp = Integer.parseInt(hex, 16);
                    sb.append((char) cp);
                    i += 4;
                } else {
                    throw new Exception("Invalid Unicode escape sequence: " + str);
                }
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

